// CloudtainerML rev0033 — Self-routing vs learned-router entropy/balance probe.
// Inspired by parameter-free Self-Routing. Not a reproduction.
#include <bits/stdc++.h>
using namespace std; static string q(const string&s){string o="\""; for(char c:s){if(c=='"'||c=='\\')o+='\\'; if(c=='\n')o+="\\n"; else o+=c;} return o+'"';}
struct Regime{string name; double hidden_align, expert_separation, balance_need, rare_expert, drift, overhead; int seed;};
struct Row{string regime,method; double acc, entropy, imbalance, rare_miss, overhead, route_flip, regret, score;};
static double C(double x){return max(0.0,min(1.0,x));}
static Row eval(const Regime&r,const string&m){double acc=0,ent=0,imb=0,rare=0,oh=0,flip=0; double base=.50+.24*r.expert_separation-.12*r.drift;
 if(m=="dense_ffn"){acc=base+.18; ent=1; imb=0; rare=0; oh=1.0; flip=0;}
 else if(m=="learned_router"){acc=base+.17+.06*r.expert_separation-.05*r.drift; ent=.62+.12*r.balance_need; imb=.22+.16*(1-r.balance_need); rare=.22*r.rare_expert; oh=.34; flip=.12+.18*r.drift;}
 else if(m=="self_routing_subspace"){acc=base+.10+.16*r.hidden_align-.08*(1-r.hidden_align)-.04*r.drift; ent=.72+.16*r.balance_need; imb=.14+.10*(1-r.hidden_align); rare=.20*r.rare_expert+.10*(1-r.hidden_align); oh=.28; flip=.08+.12*r.drift;}
 else if(m=="random_balanced_router"){acc=base+.03+.04*r.balance_need-.07*r.rare_expert; ent=.92; imb=.05; rare=.46*r.rare_expert; oh=.25; flip=.36;}
 else if(m=="hash_router"){acc=base+.02-.04*r.drift; ent=.84; imb=.12; rare=.38*r.rare_expert; oh=.22; flip=.18+.08*r.drift;}
 else if(m=="self_plus_tiny_balance_bias"){acc=base+.12+.14*r.hidden_align-.04*r.drift; ent=.80+.12*r.balance_need; imb=.08+.06*(1-r.hidden_align); rare=.14*r.rare_expert; oh=.30; flip=.10+.08*r.drift;}
 else if(m=="oracle_task_router"){acc=base+.28; ent=.88; imb=.03; rare=.03*r.rare_expert; oh=.35; flip=.03;}
 acc=C(acc); ent=C(ent); imb=C(imb); rare=C(rare); double score=(1-acc)+.22*imb+.28*rare+.12*oh*r.overhead+.16*flip-.10*ent; return {r.name,m,acc,ent,imb,rare,oh,flip,0,score};}
int main(int argc,char**argv){string out=argc>1?argv[1]:"REV0033_SELF_ROUTING_ENTROPY_SMOKE.json"; vector<Regime> regs={{"hidden_subspace_aligned",.92,.80,.45,.20,.10,.70,1},{"hidden_subspace_misaligned",.18,.82,.45,.22,.15,.70,2},{"balance_critical",.70,.65,.95,.28,.15,.90,3},{"rare_expert_critical",.64,.78,.58,.95,.20,.80,4},{"drifting_tasks",.72,.70,.54,.35,.88,.85,5},{"overhead_sensitive",.78,.72,.62,.30,.20,1.35,6}}; vector<string> methods={"dense_ffn","learned_router","self_routing_subspace","random_balanced_router","hash_router","self_plus_tiny_balance_bias","oracle_task_router"}; vector<Row> rows; map<string,int>winners,nonoracle; for(auto&r:regs){vector<Row> cand; for(auto&m:methods)cand.push_back(eval(r,m)); double best=1e9; for(auto&x:cand)best=min(best,x.score); for(auto&x:cand)x.regret=max(0.0,x.score-best); auto b=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); winners[b->method]++; auto no=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){if(a.method=="oracle_task_router")return false; if(b.method=="oracle_task_router")return true; return a.score<b.score;}); nonoracle[no->method]++; rows.insert(rows.end(),cand.begin(),cand.end());}
 ofstream f(out); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0033\",\n  \"probe\": \"self_routing_entropy\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:winners){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:nonoracle){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Parameter-free self-routing is plausible when hidden-state subspaces already encode task/expert axes; rare experts and misaligned subspaces require bias or learned repair.\",\n    \"screen_regret_fields\": [\"imbalance\", \"rare_miss\", \"route_flip\", \"regret\", \"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"acc\": "<<r.acc<<", \"entropy\": "<<r.entropy<<", \"imbalance\": "<<r.imbalance<<", \"rare_miss\": "<<r.rare_miss<<", \"overhead\": "<<r.overhead<<", \"route_flip\": "<<r.route_flip<<", \"regret\": "<<r.regret<<", \"score\": "<<r.score<<"}"<<(i+1==rows.size()?"\n":",\n");} f<<"  ]\n}\n";}
